input.new_string:
    rows.append(
        mo.vstack(
            [mo.md(f"**{name}**"), mo.hstack(cards, widths="equal", gap=0.75)],
            gap=0.5,
            align="stretch",  # let the card row span the full width...
        )
    )
# ...and stretch each strategy's row too, so `widths="equal"` splits the
# full width instead of a shrunk-to-content row (which left-aligns the cards).
return mo.vstack(rows, gap=1.5, align="stretch")

